const cfg = $('Settings').first().json;

// single-item input: one page fetch, one HTML body. The whole dependency
// surface arrives inside this one response, so there is no second item to drop.
let payload = $input.first().json;
const html = typeof payload === 'string'
  ? payload
  : String(payload.data ?? payload.body ?? '');

const site = String(cfg.your_site || '')
  .trim().replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/^www\./, '');

if (html.length < 500) {
  throw new Error(
    'Could not read ' + site + '. Check the domain opens in a browser, and that ' +
    'the Bright Data zone in Settings is a Web Unlocker zone.'
  );
}

// Hosts that are on every page and tell you nothing about who you depend on:
// social profiles, standards bodies, and the ad and analytics tags that publish
// no status API at all, so they could only ever be reported as "unknown".
const IGNORE = [
  'facebook.com','fbcdn.net','twitter.com','x.com','instagram.com','youtube.com',
  'ytimg.com','tiktok.com','pinterest.com','linkedin.com','licdn.com','reddit.com',
  'redditstatic.com','discord.com','discord.gg','whatsapp.com','telegram.org','t.me',
  'snapchat.com','sc-static.net','wikipedia.org','wikidata.org','schema.org','w3.org',
  'gmpg.org','purl.org','ogp.me','creativecommons.org','apple.com','microsoft.com',
  'mozilla.org','jquery.com','bing.com','yahoo.com','google.com','gstatic.com',
  'googleapis.com','googletagmanager.com','google-analytics.com','googlesyndication.com',
  'googleadservices.com','doubleclick.net','ggpht.com','goo.gl','example.com',
  'w.org','wp.com','gravatar.com'
];

// An asset host is rarely the brand name. Contentful serves from ctfassets.net,
// OneTrust from cookielaw.org, HubSpot from four different domains. Without this
// the watchlist is full of hosts nobody recognises and no status page resolves.
const SAME_COMPANY = {
  'shopifycdn.com':'shopify.com','shopifysvc.com':'shopify.com',
  'myshopify.com':'shopify.com','shopifyapps.com':'shopify.com',
  'shop.app':'shopify.com','shopifystatus.com':'shopify.com',
  'ctfassets.net':'contentful.com',
  'cookielaw.org':'onetrust.com','onetrust.io':'onetrust.com',
  'hsappstatic.net':'hubspot.com','hs-analytics.net':'hubspot.com',
  'hs-banner.com':'hubspot.com','hs-scripts.com':'hubspot.com',
  'hubapi.com':'hubspot.com','hsforms.net':'hubspot.com','hsforms.com':'hubspot.com',
  'hubspotusercontent-na1.net':'hubspot.com',
  'cloudflareinsights.com':'cloudflare.com','cloudflare.net':'cloudflare.com',
  'sentry-cdn.com':'sentry.io',
  'intercomcdn.com':'intercom.com','intercomassets.com':'intercom.com',
  'zdassets.com':'zendesk.com','zopim.com':'zendesk.com',
  'stripecdn.com':'stripe.com','stripe.network':'stripe.com',
  'typekit.net':'adobe.com','adobedtm.com':'adobe.com','omtrdc.net':'adobe.com',
  'algolianet.com':'algolia.com','algolia.net':'algolia.com',
  'segment.io':'segment.com',
  'appboycdn.com':'braze.com','braze.eu':'braze.com',
  'attn.tv':'attentive.com',
  'onelink.me':'appsflyer.com','appsflyer.com':'appsflyer.com',
  'bigcommerce.net':'bigcommerce.com',
  'squarespace-cdn.com':'squarespace.com',
  'wixstatic.com':'wix.com','parastorage.com':'wix.com',
  'website-files.com':'webflow.com','webflow.io':'webflow.com',
  'vercel.app':'vercel.com','vercel-insights.com':'vercel.com',
  'netlify.app':'netlify.com',
  'twiliocdn.com':'twilio.com',
  'imgix.net':'imgix.com',
  'klaviyo.com':'klaviyo.com'
};

// Where the five-pattern guess below does not land. Every entry was confirmed
// live on 2026-08-20 by reading its summary.json.
const STATUS_URL = {
  'cloudflare.com':'https://www.cloudflarestatus.com',
  'stripe.com':'https://www.stripestatus.com',
  'calendly.com':'https://www.calendlystatus.com',
  'easypost.com':'https://www.easypoststatus.com',
  'attentive.com':'https://attentive.statuspage.io',
  'auth0.com':'https://auth0.statuspage.io',
  'customer.io':'https://customer.statuspage.io',
  'onetrust.com':'https://onetrust.statuspage.io',
  'postscript.com':'https://postscript.statuspage.io',
  'sendgrid.com':'https://sendgrid.statuspage.io',
  'shippo.com':'https://shippo.statuspage.io',
  'vercel.com':'https://vercel.statuspage.io'
};

const TWO_PART_TLD = ['co','com','org','net','gov','ac','edu'];
function registrable(host) {
  const p = String(host).toLowerCase().split('.');
  if (p.length >= 3 && TWO_PART_TLD.indexOf(p[p.length - 2]) !== -1 &&
      p[p.length - 1].length === 2) {
    return p.slice(-3).join('.');
  }
  return p.length >= 2 ? p.slice(-2).join('.') : String(host).toLowerCase();
}

// Two passes with different weights. A host inside a src or href is something
// the browser genuinely loads; a host that only appears as a string in inline
// script is usually a vendor injected at runtime, which is worth catching but
// worth trusting less.
const weights = {};
function note(host, weight) {
  let d = registrable(host);
  d = SAME_COMPANY[d] || d;
  if (!d || d === site || d.indexOf(site) !== -1 || site.indexOf(d) !== -1) return;
  if (IGNORE.indexOf(d) !== -1) return;
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(d)) return;
  weights[d] = (weights[d] || 0) + weight;
}

const LOADED = /<(?:script[^>]+src|link[^>]+href|iframe[^>]+src|img[^>]+src)\s*=\s*["']([^"']+)["']/gi;
let m;
while ((m = LOADED.exec(html)) !== null) {
  const h = /^(?:https?:)?\/\/([a-z0-9.-]+\.[a-z]{2,})/i.exec(m[1]);
  if (h) note(h[1], 4);
}
const ANY = /https?:\/\/([a-z0-9.-]+\.[a-z]{2,})/gi;
while ((m = ANY.exec(html)) !== null) note(m[1], 1);

// Anything typed into Settings joins the list outright. This is the escape
// hatch for the dependencies a homepage cannot reveal - the payment processor
// behind checkout, the warehouse system, the bank.
// "Named by hand" is kept as its own flag rather than folded into the weight.
// A large sentinel looked tidy until gymshark.com turned out to mention
// shopify.com 1,027 times on one page, which pushed a discovered vendor over
// any threshold worth choosing and labelled it as one the user had typed.
const byHand = {};
for (const raw of String(cfg.also_watch || '').split(',')) {
  const d = raw.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, '');
  if (!d) continue;
  byHand[registrable(d)] = true;
  if (!(registrable(d) in weights)) weights[registrable(d)] = 0;
}

// Anything typed in Settings outranks anything merely found, then reference
// count decides. A vendor the user named is one they already know matters.
const ranked = Object.keys(weights).sort((a, b) =>
  ((byHand[b] ? 1 : 0) - (byHand[a] ? 1 : 0)) || (weights[b] - weights[a]));
const capped = ranked.slice(0, Math.max(1, Number(cfg.max_vendors) || 12));

if (!capped.length) {
  throw new Error(
    'No third-party vendors found on ' + site + '. That is unusual - list a few ' +
    'by hand in the "also_watch" field in Settings and run it again.'
  );
}

function label(d) {
  const first = d.split('.')[0].replace(/-/g, ' ');
  return first.charAt(0).toUpperCase() + first.slice(1);
}

// The news sweep costs a search per vendor, so it is aimed rather than sprayed:
// anything named by hand, plus the most heavily referenced few.
const newsDepth = Math.max(0, Number(cfg.news_sweep_top) || 0);

// A brand whose name is an ordinary English word cannot be searched for. Live
// run: shop.app produced the vendor "Shop", and a news sweep for "Shop" outage
// returned a power cut at an ice cream shop, which the classifier scored as a
// vendor outage. Those vendors keep their status probe and skip the news.
const AMBIGUOUS = [
  'shop','store','app','apps','cloud','mail','email','pay','box','wave','drive',
  'meet','chat','link','site','web','data','media','images','cdn','static',
  'assets','api','files','hub','base','core','next','plus','pro','team','work',
  'home','main','news','blog','help','support','docs','status','one','live','go'
];
function tooGenericToSearch(name) {
  const w = String(name).toLowerCase();
  return w.length <= 4 || AMBIGUOUS.indexOf(w) !== -1;
}

return capped.map((d, i) => {
  const name = label(d);
  const searchable = !tooGenericToSearch(name);
  return { json: {
    kind: 'target',
    vendor: d,
    label: name,
    refs: weights[d],
    added_by_hand: !!byHand[d],
    status_url: STATUS_URL[d] || ('https://status.' + d),
    searchable: searchable,
    watch_news: searchable && (!!byHand[d] || i < newsDepth)
  } };
});

const targets = $('Map Your Vendor Stack').all().map((i) => i.json);
const items = $input.all();

// Statuspage's own ordering, worst last. Everything downstream compares these
// numbers rather than the words, so "minor -> major" is a worsening and
// "major -> minor" is a recovery without anyone writing that table twice.
const RANK = { none: 0, maintenance: 1, minor: 2, major: 3, critical: 4 };

function clip(s, n) {
  s = String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '...' : s;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const t = targets[i] || {};
  let board = null;
  const raw = items[i].json;
  const text = typeof raw === 'string' ? raw
             : (typeof raw.data === 'string' ? raw.data : '');
  try {
    if (text) board = JSON.parse(text);
    else if (raw && raw.status) board = raw;
  } catch (e) {
    board = null;
  }

  // A body that is HTML or an error page is a real absence: something answered,
  // and it was not Statuspage. Measured 2026-08-20: status.loopreturns.com
  // returned a 427-byte error page and status.mparticle.com a 26 KB marketing
  // page, while status.govx.com - a host that does not exist - returned zero
  // bytes, and so did a Contentful probe that had worked minutes earlier.
  //
  // Nothing here can separate "this host does not exist" from "this fetch
  // failed", because both are empty. Only history can, so an empty body is
  // passed downstream as a question and Spot What Changed answers it against
  // the Data Table.
  if (!board || !board.status || !board.status.indicator) {
    out.push({ json: Object.assign({}, t, {
      kind: 'status',
      has_status_page: false,
      empty_body: !text || text.trim().length === 0,
      indicator: 'unknown', rank: 0,
      headline: 'No public status page found',
      incidents: [], degraded: [], maintenance: [], incident_id: ''
    }) });
    continue;
  }

  const indicator = String(board.status.indicator || 'none').toLowerCase();
  const incidents = (Array.isArray(board.incidents) ? board.incidents : [])
    .filter((x) => x && x.status !== 'resolved' && x.status !== 'postmortem')
    .map((x) => ({
      id: String(x.id || ''),
      name: clip(x.name, 160),
      impact: String(x.impact || 'none'),
      state: String(x.status || ''),
      started: x.started_at || x.created_at || '',
      latest: clip(((x.incident_updates || [])[0] || {}).body, 400)
    }));

  const degraded = (Array.isArray(board.components) ? board.components : [])
    .filter((c) => c && c.status && c.status !== 'operational')
    .map((c) => clip(c.name, 60) + ' (' + String(c.status).replace(/_/g, ' ') + ')')
    .slice(0, 6);

  const soon = Date.now() + 7 * 86400000;
  const maintenance = (Array.isArray(board.scheduled_maintenances) ? board.scheduled_maintenances : [])
    .filter((x) => {
      const at = Date.parse(x.scheduled_for || '');
      return !isNaN(at) && at > Date.now() && at < soon;
    })
    .map((x) => clip(x.name, 120) + ' - ' + String(x.scheduled_for).slice(0, 16))
    .slice(0, 4);

  out.push({ json: Object.assign({}, t, {
    kind: 'status',
    has_status_page: true,
    empty_body: false,
    indicator: indicator,
    rank: RANK[indicator] !== undefined ? RANK[indicator] : 0,
    headline: clip(board.status.description, 120),
    incidents: incidents,
    incident_id: (incidents[0] || {}).id || '',
    degraded: degraded,
    maintenance: maintenance
  }) });
}

return out;

const cfg = $('Settings').first().json;
// Only reached when the Filter passed something, so this node and the search
// above it ran on the same list, in the same order.
const flagged = $('Only The Ones Worth Watching').all().map((i) => i.json);
const items = $input.all();
const lookback = Math.max(1, Number(cfg.news_lookback_days) || 45);

// What a status page structurally cannot tell you. Every pattern is anchored to
// the vendor's own name and has to match within the same clause, because an
// unanchored one reads any headline the vendor is merely mentioned in. Live
// run: "Wander acquires team behind Maple, adding Shopify alumni to help build
// The Shopify of travel" was scored as Shopify being acquired.
const NEAR = '[^.!?]{0,60}';

// A label is built from a registrable domain, so it can only ever hold letters,
// digits and the spaces that replaced hyphens. Stripping anything else is
// cheaper and safer than escaping regex metacharacters that cannot occur.
function safe(x) { return String(x).replace(/[^A-Za-z0-9 ]+/g, ' ').trim(); }
const EDGE = '\\b';

function patternsFor(name) {
  const L = safe(name);
  return [
    ['breach', new RegExp(
      L + NEAR + '(data breach|breached|was hacked|ransomware|leak(ed|s)?|security incident)' +
      '|(data breach|breach|hack) (at|of) ' + L + EDGE, 'i')],
    ['shutdown', new RegExp(
      L + NEAR + '(is shutting down|shuts down|will shut down|sunset|discontinu|' +
      'end of life|winding down|ceasing operations)', 'i')],
    ['acquisition', new RegExp(
      '(acquires|acquiring|to acquire|buys|to buy) ' + L + EDGE +
      '|' + L + NEAR + '(is being acquired|has been acquired|acquired by|' +
      'to be acquired|merges with|merger with|takeover)', 'i')],
    ['outage', new RegExp(
      L + NEAR + '(outage|is down|was down|went down|downtime|disruption|degraded|' +
      'service interruption)|(outage|downtime|disruption)' + NEAR + L + EDGE, 'i')],
    ['layoffs', new RegExp(
      L + NEAR + '(layoff|lays off|laid off|job cuts|cutting jobs|redundanc)' +
      '|(layoffs?|job cuts|cutting jobs)' + NEAR + L + EDGE, 'i')],
    ['pricing', new RegExp(
      L + NEAR + '(price increase|raising prices|price hike|new pricing|pricing change)', 'i')]
  ];
}

// A public vendor's news is mostly its share price. "Shares Acquired by
// Atreides Management LP" is a fund buying stock, not the vendor being bought,
// and it matched the acquisition pattern until this was added.
const MARKET_NOISE = /(shares?|stake|stock|price target|analysts?|investors?|earnings|quarterly results|nyse|nasdaq|market cap|holdings?|\$[A-Z]{2,5}\b|buy rating|sell rating)/i;

function ageDays(d) {
  if (!d) return null;
  const rel = /(\d+)\s+(hour|day|week|month|year)s?\s+ago/i.exec(d);
  if (rel) {
    const mult = { hour: 1 / 24, day: 1, week: 7, month: 30, year: 365 };
    return Math.round(Number(rel[1]) * (mult[rel[2].toLowerCase()] || 1));
  }
  const t = Date.parse(d);
  return isNaN(t) ? null : Math.round((Date.now() - t) / 86400000);
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const t = flagged[i] || {};
  let body = items[i].json;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
  if (typeof body.body === 'string') { try { body = JSON.parse(body.body); } catch (e) { /* keep */ } }

  // Bright Data answers a bad query with HTTP 200 and an error body, which
  // neverError hands straight through. Saying so beats reporting no news.
  if (body && body.error) {
    out.push({ json: { kind: 'news', vendor: t.vendor, label: t.label,
      signals: [], note: 'Search failed: ' + String(body.error).slice(0, 120) } });
    continue;
  }

  const rows = Array.isArray(body && body.news) ? body.news
             : (Array.isArray(body && body.organic) ? body.organic : []);
  const patterns = patternsFor(t.label || '');
  const named = new RegExp(EDGE + safe(t.label || '') + EDGE, 'i');
  const signals = [];
  for (const r of rows) {
    const title = String(r.title || '');
    if (!title) continue;
    // The vendor has to be named as a whole word, not matched inside another.
    if (!named.test(title)) continue;
    if (MARKET_NOISE.test(title)) continue;
    const age = ageDays(r.date);
    if (age !== null && age > lookback) continue;
    const hit = patterns.find((k) => k[1].test(title));
    if (!hit) continue;
    signals.push({
      kind: hit[0], title: title.slice(0, 180),
      source: String(r.source || '').slice(0, 60),
      when: String(r.date || ''), link: String(r.link || '')
    });
    if (signals.length >= 4) break;
  }

  out.push({ json: { kind: 'news', vendor: t.vendor, label: t.label, signals: signals } });
}

return out;

const cfg = $('Settings').first().json;

// Input is the memory table. On the very first run it is empty, which is why
// the read above has alwaysOutputData - without it this node never runs, the
// baseline is never written, and the workflow silently never starts working.
const remembered = {};
for (const row of $input.all()) {
  const r = row.json || {};
  if (r.vendor) remembered[r.vendor] = r;
}

// Both evidence streams come out of the Merge together. Reading them from this
// node's own input rather than by node name is deliberate: the news branch does
// not run at all when the Filter passes nothing, and $('Read The Headlines')
// would throw on exactly the quiet days this has to survive.
const status = {};
const news = {};
for (const item of $('Combine Both Signals').all()) {
  const s = item.json || {};
  if (s.kind === 'status') status[s.vendor] = s;
  else if (s.kind === 'news') news[s.vendor] = s;
}

// Nothing remembered means this has never run against this site. A first run
// that reports nothing looks broken, and "here is everything you depend on" is
// the one report worth sending in full, so the baseline is the report.
const firstRun = Object.keys(remembered).length === 0;

const HARD = ['breach', 'shutdown'];
const SOFT = ['outage', 'acquisition'];

const out = [];
for (const vendor of Object.keys(status)) {
  const s = status[vendor];
  const n = news[vendor] || { signals: [] };
  const prev = remembered[vendor] || {};
  const sigs = Array.isArray(n.signals) ? n.signals : [];
  const kinds = sigs.map((x) => x.kind);
  const newsKey = kinds.slice().sort().join(',');

  const prevRank = prev.indicator === undefined ? null : (
    { unknown: 0, none: 0, maintenance: 1, minor: 2, major: 3, critical: 4 }[prev.indicator] ?? 0
  );

  // An empty answer from a vendor whose status page has been read before is a
  // failed fetch, not a vendor that lost its status page overnight. Reporting
  // it as a change would alert on the network, and writing it to the table
  // would erase what was known and manufacture a second alert on the next run
  // when the real status came back. So the last known state is carried forward
  // untouched and the vendor is listed as unreachable for this run only.
  const knownGood = prev.vendor && prev.indicator && prev.indicator !== 'unknown';
  if (s.empty_body && knownGood) {
    out.push({ json: {
      vendor: vendor, label: s.label,
      indicator: String(prev.indicator || 'unknown'),
      incident_id: String(prev.incident_id || ''),
      news_key: String(prev.news_key || ''),
      last_change: String(prev.last_change || ''),
      has_status_page: prev.vendor ? true : null,
      probe_failed: true,
      headline: s.headline, incidents: [], degraded: [], maintenance: [],
      signals: sigs, refs: s.refs, searchable: s.searchable !== false,
      added_by_hand: !!s.added_by_hand,
      reasons: [], changed: false, first_run: firstRun, severity: 'watch'
    } });
    continue;
  }

  const reasons = [];
  if (s.incident_id && s.incident_id !== String(prev.incident_id || '')) {
    reasons.push('a new incident is open');
  } else if (prevRank !== null && s.rank > prevRank) {
    reasons.push('the status got worse');
  } else if (prevRank !== null && prevRank >= 2 && s.rank === 0) {
    reasons.push('recovered since the last check');
  }
  if (newsKey && newsKey !== String(prev.news_key || '')) reasons.push('news signal');
  if (s.maintenance.length && !prev.vendor) reasons.push('maintenance is scheduled');
  if (!s.has_status_page && !prev.vendor) reasons.push('no public status page');
  if (firstRun) reasons.push('first check - this is the baseline');

  // Severity is decided here, in code, and the model never gets to move it. A
  // risk tool that lets a language model downgrade a breach is not a risk tool.
  let severity = 'watch';
  if (kinds.some((k) => HARD.indexOf(k) !== -1) || s.rank >= 3) severity = 'critical';
  else if (kinds.some((k) => SOFT.indexOf(k) !== -1) || s.rank === 2) severity = 'elevated';

  out.push({ json: {
    vendor: vendor,
    label: s.label,
    indicator: s.indicator,
    incident_id: s.incident_id || '',
    news_key: newsKey,
    last_change: new Date().toISOString().slice(0, 16).replace('T', ' '),
    has_status_page: !!s.has_status_page,
    headline: s.headline,
    incidents: s.incidents,
    degraded: s.degraded,
    maintenance: s.maintenance,
    signals: sigs,
    refs: s.refs,
    searchable: s.searchable !== false,
    added_by_hand: !!s.added_by_hand,
    reasons: reasons,
    changed: reasons.length > 0,
    first_run: firstRun,
    severity: severity
  } });
}

// One item per vendor, always. The write below has to see every vendor or the
// memory goes stale for the quiet ones, and a filtering node that can return
// nothing would end this branch entirely.
return out;

const cfg = $('Settings').first().json;
const all = $input.all().map((i) => i.json);

const RANK = { critical: 3, elevated: 2, watch: 1 };
const minimum = String(cfg.report_from || 'elevated').toLowerCase();
const floorRank = RANK[minimum] || 2;

// The severity floor is what keeps a daily brief quiet. It does not apply to
// the first run, where the whole inventory is the point of the report.
const baseline = all.length > 0 && all.every((v) => v.first_run);

const alerts = all
  .filter((v) => v.changed && (baseline || (RANK[v.severity] || 1) >= floorRank))
  .sort((a, b) => (RANK[b.severity] || 1) - (RANK[a.severity] || 1));

const blind = all.filter((v) => v.has_status_page === false).map((v) => v.label);
const unreachable = all.filter((v) => v.probe_failed).map((v) => v.label);
const unsearchable = all.filter((v) => v.searchable === false).map((v) => v.label);
const worst = alerts.length ? alerts[0].severity : 'clear';

// The model reads this and nothing else. Composing it here keeps the prompt a
// fixed shape whatever the vendors are, and keeps the raw payloads - one of
// which measured 215 KB - out of the context entirely.
const lines = [];
for (const a of alerts) {
  lines.push('VENDOR: ' + a.label + ' (' + a.vendor + ')');
  lines.push('  status: ' + a.indicator + ' - ' + a.headline);
  lines.push('  flagged because: ' + a.reasons.join('; '));
  for (const inc of (a.incidents || []).slice(0, 2)) {
    lines.push('  incident: [' + inc.impact + '/' + inc.state + '] ' + inc.name);
    if (inc.latest) lines.push('    latest update: ' + inc.latest);
  }
  if ((a.degraded || []).length) lines.push('  degraded: ' + a.degraded.join(', '));
  if ((a.maintenance || []).length) lines.push('  maintenance: ' + a.maintenance.join(' | '));
  for (const s of (a.signals || [])) {
    lines.push('  news [' + s.kind + ', ' + s.when + ']: ' + s.title + ' (' + s.source + ')');
  }
  lines.push('');
}

// Exactly one item, every run, whatever happened. The Switch below routes on
// one value and cannot be handed an empty stream.
return [{ json: {
  alert_count: alerts.length,
  stack_size: all.length,
  worst: worst,
  alerts: alerts,
  blind_spots: blind,
  unreachable: unreachable,
  unsearchable: unsearchable,
  baseline: baseline,
  site: cfg.your_site,
  // A baseline needs no interpretation, so the model is handed one line
  // instead of the whole inventory rather than being cut out of the graph.
  evidence: baseline
    ? 'First run against ' + cfg.your_site + '. Inventory only, no judgement needed.'
    : (lines.join('\n') || 'Nothing changed since the last check.')
} }];

const cfg = $('Settings').first().json;
const roll = $('Roll Up The Findings').first().json;

// single-item input: Roll Up The Findings emits exactly one item every run, so
// the extractor above returns exactly one judgement set. There is no second
// item here to drop.
//
// The Information Extractor nests its result under `output`. Reading $json
// directly returns undefined on every field, which produces an empty brief on a
// run where every node is green.
const raw = $input.first().json;
const parsed = (raw && raw.output) || raw || {};
const judged = Array.isArray(parsed.assessments) ? parsed.assessments : [];
const byVendor = {};
for (const j of judged) {
  if (j && j.vendor) byVendor[String(j.vendor).toLowerCase()] = j;
}

// Three templates in a row came back with categories nobody defined, so the
// model's answer is never trusted as an enum - only as prose.
const ICON = { critical: ':rotating_light:', elevated: ':warning:', watch: ':eyes:' };
const WORD = { critical: 'Act now', elevated: 'Worth a look', watch: 'Noted' };

// Slack and email are written side by side rather than one being derived from
// the other. Stripping Slack's markup out of a finished message turned
// :rotating_light: into :rotatinglight: on the first live run, because the
// underscore inside an emoji name is also Slack's italic marker.
const slack = [];
const mail = [];
function both(slackLine, mailLine) {
  slack.push(slackLine);
  mail.push(mailLine === undefined ? slackLine : mailLine);
}

both('*Vendor stack check - ' + roll.site + '*', 'Vendor stack check - ' + roll.site);
both(roll.baseline
  ? 'First check. These are the ' + roll.stack_size +
    ' third parties this site runs on, and where each one stands today.'
  : roll.alert_count + ' of ' + roll.stack_size +
    ' watched vendors changed since the last check.');
both('');

for (const a of roll.alerts) {
  const j = byVendor[String(a.label).toLowerCase()] ||
            byVendor[String(a.vendor).toLowerCase()] || {};
  const verdict = WORD[a.severity] || 'Noted';
  both((ICON[a.severity] || ':eyes:') + ' *' + a.label + '* - ' + verdict,
       String(a.label).toUpperCase() + ' - ' + verdict);

  const state = a.has_status_page
    ? (a.indicator === 'unknown' ? 'status unknown' : a.indicator + ' - ' + a.headline)
    : 'no public status page';
  both('> ' + state, '    ' + state);
  if (a.reasons.length) {
    both('> flagged because: ' + a.reasons.join('; '),
         '    flagged because: ' + a.reasons.join('; '));
  }
  for (const inc of (a.incidents || []).slice(0, 1)) {
    both('> incident: ' + inc.name, '    incident: ' + inc.name);
  }
  for (const sig of (a.signals || []).slice(0, 2)) {
    both('> ' + sig.kind + ': ' + sig.title + (sig.link ? ' <' + sig.link + '|link>' : ''),
         '    ' + sig.kind + ': ' + sig.title + (sig.link ? ' ' + sig.link : ''));
  }
  // On a first run there is nothing to interpret, and asking anyway produced
  // eight rows of "no immediate action is required as all systems are
  // operational". The inventory is the message.
  if (!roll.baseline && j.what_it_means) {
    both('> *What it means:* ' + j.what_it_means, '    What it means: ' + j.what_it_means);
  }
  if (!roll.baseline && j.do_now) both('> *Do now:* ' + j.do_now, '    Do now: ' + j.do_now);
  both('');
}

if ((roll.blind_spots || []).length) {
  const note = 'No public status page, so no early warning is possible for: ' +
               roll.blind_spots.join(', ') + '.';
  both('_' + note + '_', note);
}
if ((roll.unreachable || []).length) {
  const note = 'Could not reach the status page for ' + roll.unreachable.join(', ') +
               ' this run. Their last known state is unchanged - this is about the ' +
               'check, not about them.';
  both('_' + note + '_', note);
}
if ((roll.unsearchable || []).length) {
  const note = 'News sweep skipped for ' + roll.unsearchable.join(', ') +
               ' - the brand name is an ordinary word, so the results are noise.';
  both('_' + note + '_', note);
}

const subject = roll.baseline
  ? 'Vendor stack baseline for ' + roll.site + ' - ' + roll.stack_size + ' third parties'
  : (roll.worst === 'critical' ? '[ACT NOW] ' : '') +
    roll.alert_count + ' vendor change' + (roll.alert_count === 1 ? '' : 's') +
    ' on ' + roll.site;

return [{ json: {
  // A first run has nothing to compare against, so every vendor scores "watch"
  // and the Switch would file the whole inventory away unseen. The baseline is
  // the one report worth reading, so it is posted - but it is not an emergency,
  // so it takes the Slack lane rather than the one that sends mail.
  severity: roll.baseline ? 'elevated' : roll.worst,
  alert_count: roll.alert_count,
  subject: subject,
  message: slack.join('\n'),
  email_body: mail.join('\n')
} }];
